{"test": "perf_get", "handle": "VIEW_GET", "resolve": "OWNER.method("get", 1)", "erased": "MethodType.methodType(Object.class, Object.class, int.class)", "setup": "jdk.internal.m3.M3IndexedArray<Integer> backing = new jdk.internal.m3.M3IndexedArray<>();
        List<Integer> expected = new ArrayList<>();
        for (int i = 0; i < LARGE; i++) {
            backing.append(i);
            if (i % 2 == 0) {
                expected.add(i);
            }
        }
        Object view = backing.filtered(v -> v % 2 == 0);
        int size = expected.size();", "m3_op": "check += (Integer) (Object) VIEW_GET.invokeExact(view, op % size);", "jdk_op": "jdkCheck += expected.get(op % size);", "baseline": "ArrayList.get(int)"}

{"test": "perf_codePointCount", "handle": "CODE_POINT_COUNT", "resolve": "new Access("java.lang.M3StringCodePointPrecompute$Geometry").method("codePointCount", 2)", "erased": "MethodType.methodType(int.class, Object.class, int.class, int.class)", "setup": "new Access("java.lang.M3String").method("activate", 1).invoke((String) null);
