        int n = s.length();
        int half = n / 2;
        Object m3 = new Access("java.lang.M3StringPool").method("internChars", 3).invoke(s.toCharArray(), 0, n);
        Object g = OWNER.method("prepare", 1).invoke(m3);", "m3_op": "int begin = op % half;
                check += (int) CODE_POINT_COUNT.invokeExact(g, begin, begin + half);", "jdk_op": "int begin = op % half;
                jdkCheck += s.codePointCount(begin, begin + half);", "baseline": "String.codePointCount(int,int)"}

