{"test": "perf_charAt", "handle": "LANE_CHAR_AT", "resolve": "OWNER.method("charAt", 3)", "erased": "MethodType.methodType(char.class, Object.class, byte[].class, byte.class, int.class)", "setup": "Access laneType = new Access("java.lang.M3StringBuilderLane");
        Object lane = laneType.constructor("M3StringBuilderLane", 1).invoke(LARGE);
        byte latin1 = (byte) new Access("java.lang.String").constant("LATIN1");
        String head = "flat-head-";
        String piece = "piece-text-".repeat(SMALL);
        StringBuilder logical = new StringBuilder(head);
        laneType.method("push", 5).invoke(lane, piece, 0, piece.length(), head.length(), latin1);
        logical.append(piece);
        byte[] flat = head.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
        int length = logical.length();", "m3_op": "check += (char) LANE_CHAR_AT.invokeExact(lane, flat, latin1, op % length);", "jdk_op": "jdkCheck += logical.charAt(op % length);", "baseline": "StringBuilder.charAt(int)"}
